<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php'; require_role(['admin','staff']); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $cid=(int)($_POST['customer_id']??0);$action=$_POST['action']??'';$reason=trim($_POST['reason']??'');
 if(!in_array($action,['disconnect','reconnect'],true)||$reason===''){flash('error','Choose an action and provide a reason.');redirect('service.php');}
 $pdo->beginTransaction();try{$s=$pdo->prepare("SELECT * FROM customers WHERE id=? FOR UPDATE");$s->execute([$cid]);$c=$s->fetch();if(!$c)throw new RuntimeException('Customer not found.');
 $new=$action==='disconnect'?'disconnected':'active';if($action==='reconnect'&&$c['status']==='inactive')throw new RuntimeException('An inactive account cannot be reconnected.');if($action==='disconnect'&&$c['status']==='disconnected')throw new RuntimeException('This customer is already disconnected.');
 $pdo->prepare("UPDATE customers SET status=? WHERE id=?")->execute([$new,$cid]);$pdo->prepare("INSERT INTO service_actions(customer_id,action,reason,performed_by) VALUES(?,?,?,?)")->execute([$cid,$action,$reason,current_user()['id']]);$u=$pdo->prepare("SELECT id FROM users WHERE customer_id=?");$u->execute([$cid]);$uid=$u->fetchColumn();if($uid)add_notification($pdo,(int)$uid,"Your water service status has been updated to {$new}. Reason: {$reason}");audit($pdo,strtoupper($action),"Customer #$cid: $reason");$pdo->commit();flash('success','Service status updated.');
 }catch(Throwable $e){$pdo->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'Could not update service status.');}redirect('service.php');
}
$customers=$pdo->query("SELECT id,account_number,full_name,status FROM customers ORDER BY full_name")->fetchAll();$rows=$pdo->query("SELECT s.*,c.full_name,c.account_number,u.name AS staff_name FROM service_actions s JOIN customers c ON c.id=s.customer_id LEFT JOIN users u ON u.id=s.performed_by ORDER BY s.created_at DESC LIMIT 100")->fetchAll();$pageTitle='Service actions';require 'includes/header.php';
?>
<div class="two-col"><div class="panel"><h3>Disconnect / reconnect</h3><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Customer account *</label><select name="customer_id" required><option value="">Select customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['account_number'].' · '.$c['full_name'].' · '.$c['status'])?></option><?php endforeach;?></select><label>Action *</label><select name="action"><option value="disconnect">Disconnect service</option><option value="reconnect">Reconnect service</option></select><label>Reason *</label><textarea name="reason" required rows="3" placeholder="Record the reason for this action"></textarea><button class="btn primary">Update service status</button><p class="hint">Only perform service actions in accordance with the utility's approved procedures and customer notice requirements.</p></form></div><div class="panel"><h3>Important controls</h3><ul class="feature-list"><li>Every action records the staff member and reason.</li><li>Customers receive an in-system notification if they have a portal account.</li><li>Reconnect actions cannot be applied to inactive customer accounts.</li><li>Check payment records and utility policy before disconnection.</li></ul></div></div>
<div class="panel"><h3>Service action history</h3><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Action</th><th>Reason</th><th>Performed by</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><small class="table-sub"><?=e($r['account_number'])?></small></td><td><span class="pill <?=$r['action']==='reconnect'?'success':'danger'?>"><?=e(ucfirst($r['action']))?></span></td><td><?=e($r['reason'])?></td><td><?=e($r['staff_name']??'—')?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No service actions recorded.</td></tr><?php endif;?></tbody></table></div></div>
<?php require 'includes/footer.php';?>
